def is_enabled(flag, user_id, context=None):
    """Evaluate a feature flag for a user.

    flag is a dict like {"type": "boolean", "value": True} or
    {"type": "allowlist", "users": [...]}. Unknown types raise ValueError.
    """
    context = context or {}
    if flag["type"] == "boolean":
        return bool(flag["value"])
    if flag["type"] == "allowlist":
        return user_id in flag["users"]
    raise ValueError(f"unknown flag type: {flag['type']!r}")

