from flags import is_enabled


def test_boolean_and_allowlist_unaffected():
    assert is_enabled({"type": "boolean", "value": True}, "u1") is True
    assert is_enabled({"type": "allowlist", "users": ["u1"]}, "u2") is False


def test_percentage_is_deterministic():
    flag = {"type": "percentage", "name": "new-nav", "rollout": 50}
    first = is_enabled(flag, "user-42")
    for _ in range(20):
        assert is_enabled(flag, "user-42") == first


def test_percentage_0_and_100_are_absolute():
    off = {"type": "percentage", "name": "beta", "rollout": 0}
    on = {"type": "percentage", "name": "beta", "rollout": 100}
    users = [f"user-{i}" for i in range(200)]
    assert all(is_enabled(off, u) is False for u in users)
    assert all(is_enabled(on, u) is True for u in users)


def test_different_flags_give_different_rollout_sets():
    # Two independent 50% flags must NOT enable the exact same users -
    # a bucket keyed only on user_id (ignoring the flag name) would.
    flag_a = {"type": "percentage", "name": "flag-a", "rollout": 50}
    flag_b = {"type": "percentage", "name": "flag-b", "rollout": 50}
    users = [f"user-{i}" for i in range(300)]
    enabled_a = {u for u in users if is_enabled(flag_a, u)}
    enabled_b = {u for u in users if is_enabled(flag_b, u)}
    assert enabled_a != enabled_b, (
        "two different percentage flags produced the identical enabled-user "
        "set - the bucket must be keyed on (flag name, user), not user alone"
    )


def test_rollout_is_roughly_the_requested_share():
    flag = {"type": "percentage", "name": "spread-check", "rollout": 30}
    users = [f"user-{i}" for i in range(2000)]
    enabled = sum(1 for u in users if is_enabled(flag, u))
    assert 500 <= enabled <= 700, f"expected roughly 30% of 2000 (~600), got {enabled}"

