import hashlib


def _bucket(flag_name, user_id):
    """Deterministic 0-99 bucket for (flag_name, user_id): same inputs
    always give the same bucket, buckets spread ~uniformly over users."""
    digest = hashlib.sha256(f"{flag_name}:{user_id}".encode("utf-8")).hexdigest()
    return int(digest[:8], 16) % 100


def is_enabled(flag, user_id, context=None):
    """Evaluate a feature flag for a user.

    flag is a dict like {"type": "boolean", "value": True},
    {"type": "allowlist", "users": [...]}, or
    {"type": "percentage", "name": "...", "rollout": 0-100}. Unknown types
    raise ValueError.
    """
    context = context or {}
    if flag["type"] == "boolean":
        return bool(flag["value"])
    if flag["type"] == "allowlist":
        return user_id in flag["users"]
    if flag["type"] == "percentage":
        return _bucket(flag["name"], user_id) < flag["rollout"]
    raise ValueError(f"unknown flag type: {flag['type']!r}")

